∀ (n : Nat),
  NativeBridge.positiveOf n =
    if n < 2 then Rocq.Corelib.Numbers.BinNums.positive.xH
    else
      if n % 2 = 0 then Rocq.Corelib.Numbers.BinNums.positive.xO (NativeBridge.positiveOf (n / 2))
      else Rocq.Corelib.Numbers.BinNums.positive.xI (NativeBridge.positiveOf (n / 2))

